# region: intake
def intake(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: shape
def shape(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(sift(gather(shape(fold(intake(raw))))))

